:root {
  color-scheme: light;
  --paper: #f4f1ea;
  --ink: #1a1a1a;
  --line: #1a1a1a;
  font-family: 'Courier New', 'Space Mono', monospace;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: var(--paper);
  color: var(--ink);
  background-image: radial-gradient(#00000014 1px, transparent 1px);
  background-size: 22px 22px;
}

.app {
  height: 100%;
  display: flex;
  flex-direction: column;
}

/* ---------- toolbar ---------- */

.toolbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--paper);
  border-bottom: 3px solid var(--line);
}

.toolbar__brand {
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: 0.02em;
  margin-right: 8px;
}

.toolbar__btn {
  font-family: inherit;
  font-size: 0.85rem;
  background: #fff;
  border: 2px solid var(--line);
  padding: 6px 12px;
  cursor: pointer;
  box-shadow: 3px 3px 0 var(--line);
}

.toolbar__btn:hover {
  transform: translate(1px, 1px);
  box-shadow: 2px 2px 0 var(--line);
}

.toolbar__btn--ghost {
  margin-left: auto;
  background: transparent;
}

.toolbar__colors {
  display: flex;
  gap: 6px;
  padding: 0 6px;
  border-left: 2px solid var(--line);
  border-right: 2px solid var(--line);
  margin: 0 4px;
}

.toolbar__swatch {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--line);
  cursor: pointer;
  padding: 0;
}

.toolbar__swatch--active {
  outline: 2px solid var(--ink);
