import { useBoard } from './state/useBoard.js'
import Board from './components/Board.jsx'
import Toolbar from './components/Toolbar.jsx'

export default function App() {
  const { board, addCard, updateCard, moveCard, removeCard, addTask, toggleTask, removeTask, resetBoard } =
    useBoard()

  return (
    <div className="app">
      <Toolbar onAddCard={addCard} onReset={resetBoard} />
      <Board
        board={board}
        actions={{ updateCard, moveCard, removeCard, addTask, toggleTask, removeTask }}
      />
    </div>
  )
}

import { useState } from 'react'
import { COLORS, DEFAULT_COLOR } from '../data/board.js'

export default function Toolbar({ onAddCard, onReset }) {
  const [color, setColor] = useState(DEFAULT_COLOR)

  function place() {
    // scatter new cards a bit so they don't stack exactly
    const x = 100 + Math.round(Math.random() * 300)
    const y = 100 + Math.round(Math.random() * 200)
    return { x, y, color }
  }

  return (
    <div className="toolbar">
      <span className="toolbar__brand">Kanvy</span>

      <button className="toolbar__btn" onClick={() => onAddCard('note', place())}>
        + Note
      </button>
      <button className="toolbar__btn" onClick={() => onAddCard('task', place())}>
        + Task list
      </button>

      <div className="toolbar__colors">
        {Object.entries(COLORS).map(([name, hex]) => (
          <button
            key={name}
            className={`toolbar__swatch${color === name ? ' toolbar__swatch--active' : ''}`}
            style={{ background: hex }}
            title={name}
            onClick={() => setColor(name)}
          />
        ))}
      </div>

      <button className="toolbar__btn toolbar__btn--ghost" onClick={onReset}>
        Reset board
      </button>
    </div>
  )
}

import { useRef, useState } from 'react'
import { COLORS } from '../data/board.js'

export default function Card({
  card,
  onMove,
  onUpdate,
  onRemove,
  onAddTask,
  onToggleTask,
  onRemoveTask,
}) {
  const dragRef = useRef(null)
  const [dragging, setDragging] = useState(false)
  const [newTaskText, setNewTaskText] = useState('')

  function handlePointerDown(e) {
    // don't start a drag from interactive children
    if (e.target.closest('.no-drag')) return
    const startX = e.clientX
    const startY = e.clientY
    const originX = card.x
    const originY = card.y
    dragRef.current = { startX, startY, originX, originY }
    setDragging(true)
    e.target.setPointerCapture(e.pointerId)
  }

  function handlePointerMove(e) {
    if (!dragRef.current) return
    const { startX, startY, originX, originY } = dragRef.current
    const dx = e.clientX - startX
    const dy = e.clientY - startY
    onMove(card.id, originX + dx, originY + dy)
  }

  function handlePointerUp(e) {
    dragRef.current = null
    setDragging(false)
    try {
      e.target.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
  }

  function submitNewTask(e) {
    e.preventDefault()
    const text = newTaskText.trim()
    if (!text) return
    onAddTask(card.id, text)
    setNewTaskText('')
  }

  return (
    <div
      className={`card${dragging ? ' card--dragging' : ''}`}
      style={{ left: card.x, top: card.y, width: card.w, borderColor: COLORS[card.color] }}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
    >
      <div className="card__bar">
        <span className="card__dot" style={{ background: COLORS[card.color] }} />
        <input
          className="card__title no-drag"
          value={card.title}
          onChange={(e) => onUpdate(card.id, { title: e.target.value })}
        />
        <button className="card__close no-drag" onClick={() => onRemove(card.id)} title="Remove card">
          ×
        </button>
      </div>

      {card.type === 'note' && (
        <textarea
          className="card__content no-drag"
          value={card.content}
          placeholder="Write something..."
          onChange={(e) => onUpdate(card.id, { content: e.target.value })}
        />
      )}

      {card.type === 'task' && (
        <div className="card__tasks">
          {card.tasks.map((t) => (
            <label key={t.id} className="task-row no-drag">
              <input
                type="checkbox"
                checked={t.done}
                onChange={() => onToggleTask(card.id, t.id)}
              />
              <span className={t.done ? 'task-row__text task-row__text--done' : 'task-row__text'}>
                {t.text}
              </span>
              <button
                className="task-row__remove"
                onClick={() => onRemoveTask(card.id, t.id)}
                title="Remove task"
              >
                ×
              </button>
            </label>
          ))}
          <form className="task-add no-drag" onSubmit={submitNewTask}>
            <input
              value={newTaskText}
              onChange={(e) => setNewTaskText(e.target.value)}
              placeholder="+ add task"
            />
          </form>
        </div>
      )}
    </div>
  )
}

