.card__bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border-bottom: 2px solid var(--line);
}

.card__dot {
  flex: 0 0 auto;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid var(--line);
}

.card__title {
  flex: 1 1 auto;
  min-width: 0;
  font-family: inherit;
  font-weight: 700;
  font-size: 0.9rem;
  border: none;
  background: transparent;
  cursor: text;
}

.card__title:focus {
  outline: none;
  text-decoration: underline;
}

.card__close {
  flex: 0 0 auto;
  border: none;
  background: transparent;
  font-size: 1rem;
  line-height: 1;
  cursor: pointer;
  padding: 2px 4px;
}

.card__close:hover {
  color: #d33;
}

.card__content {
  display: block;
  width: 100%;
  min-height: 64px;
  border: none;
  resize: vertical;
  font-family: inherit;
  font-size: 0.85rem;
  padding: 8px;
  background: transparent;
  cursor: text;
}

.card__content:focus {
  outline: none;
}

.card__tasks {
  padding: 6px 8px 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.task-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.85rem;
  cursor: default;
  padding: 2px 0;
}

.task-row__text {
  flex: 1 1 auto;
}

.task-row__text--done {
  text-decoration: line-through;
  opacity: 0.5;
}

.task-row__remove {
  border: none;
  background: transparent;
  cursor: pointer;
  opacity: 0;
  padding: 0 4px;
}

.task-row:hover .task-row__remove {
  opacity: 0.6;
}

.task-row__remove:hover {
  opacity: 1;
  color: #d33;
}

.task-add {
  margin-top: 4px;
}

.task-add input {
  width: 100%;
  border: none;
  border-top: 1px dashed #999;
  font-family: inherit;
  font-size: 0.85rem;
  padding: 6px 0 2px;
  background: transparent;
  cursor: text;
}

.task-add input:focus {
  outline: none;
}

