import Card from './Card.jsx'

export default function Board({ board, actions }) {
  return (
    <div className="board">
      {board.cards.map((card) => (
        <Card
          key={card.id}
          card={card}
          onMove={actions.moveCard}
          onUpdate={actions.updateCard}
          onRemove={actions.removeCard}
          onAddTask={actions.addTask}
          onToggleTask={actions.toggleTask}
          onRemoveTask={actions.removeTask}
        />
      ))}
    </div>
  )
}
